create extension if not exists "pgcrypto";
create type public.app_role as enum ('super_admin','admin');
create type public.product_category as enum ('cement','brick','terazone','service');
create type public.pay_type as enum ('monthly','daily','weekly');
create type public.sale_status as enum ('open','paid','void');
create type public.payroll_status as enum ('draft','approved','paid','void');
create table public.company_settings (id boolean primary key default true check (id), display_name text not null default 'Damena', currency_code text not null default 'ETB', timezone text not null default 'Africa/Addis_Ababa', default_locale text not null default 'am', updated_at timestamptz not null default now());
insert into public.company_settings default values on conflict do nothing;
create table public.profiles (id uuid primary key references auth.users(id) on delete restrict, display_name text, role public.app_role not null default 'admin', locale text not null default 'am' check(locale in ('am','en')), is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index one_active_super_admin on public.profiles(role) where role='super_admin' and is_active;
create table public.products (id uuid primary key default gen_random_uuid(), name text not null, sku text unique, category public.product_category not null, unit text not null default 'piece', selling_price numeric(14,2) check(selling_price is null or selling_price>=0), stock_on_hand numeric(14,3) not null default 0 check(stock_on_hand>=0), low_stock_threshold numeric(14,3) not null default 0 check(low_stock_threshold>=0), is_stock_tracked boolean not null default true, is_active boolean not null default true, created_by uuid references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.inventory_movements (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id), quantity_delta numeric(14,3) not null check(quantity_delta<>0), movement_type text not null check(movement_type in ('receipt','adjustment','sale_reversal','sale')), reason text not null, reference text, recorded_by uuid references public.profiles(id), created_at timestamptz not null default now());
create sequence public.invoice_number_seq;
create table public.sales (id uuid primary key default gen_random_uuid(), invoice_number text not null unique default ('INV-'||to_char(current_date,'YYYYMMDD')||'-'||lpad(nextval('public.invoice_number_seq')::text,5,'0')), sale_date date not null default current_date, customer_name text, total_amount numeric(14,2) not null default 0, paid_amount numeric(14,2) not null default 0 check(paid_amount>=0), payment_method text check(payment_method in ('cash','bank_transfer','mobile','other')), status public.sale_status not null default 'open', notes text, has_service_lines boolean not null default false, created_by uuid references public.profiles(id), created_at timestamptz not null default now(), voided_at timestamptz, void_reason text, check(paid_amount<=total_amount));
create table public.sale_lines (id uuid primary key default gen_random_uuid(), sale_id uuid not null references public.sales(id) on delete restrict, product_id uuid references public.products(id), item_name_snapshot text not null, unit_snapshot text not null, quantity numeric(14,3) not null check(quantity>0), unit_price numeric(14,2) not null check(unit_price>=0), line_total numeric(14,2) generated always as (quantity*unit_price) stored);
create table public.payments (id uuid primary key default gen_random_uuid(), sale_id uuid not null references public.sales(id), amount numeric(14,2) not null check(amount>0), payment_method text not null, paid_at timestamptz not null default now(), recorded_by uuid references public.profiles(id));
create table public.employees (id uuid primary key default gen_random_uuid(), name text not null, employee_number text unique, contact text, is_active boolean not null default true, pay_type public.pay_type not null, rate numeric(14,2) not null check(rate>=0), created_by uuid references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.payroll_records (id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.employees(id), pay_type public.pay_type not null, period_start date not null, period_end date, quantity numeric(14,3) not null default 1 check(quantity>0), rate_snapshot numeric(14,2) not null check(rate_snapshot>=0), amount numeric(14,2) not null check(amount>=0), status public.payroll_status not null default 'draft', notes text, payment_method text, paid_at timestamptz, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create unique index monthly_payroll_once on public.payroll_records(employee_id,period_start) where pay_type='monthly' and status<>'void';
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references public.profiles(id), action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index products_category_active on public.products(category,is_active); create index inventory_product_date on public.inventory_movements(product_id,created_at desc); create index sales_date on public.sales(sale_date desc); create index payroll_period on public.payroll_records(period_start desc);
create function public.current_role() returns public.app_role language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() and is_active $$;
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select public.current_role() in ('admin','super_admin') $$;
create function public.is_super_admin() returns boolean language sql stable security definer set search_path=public as $$ select public.current_role()='super_admin' $$;
create function public.audit(p_action text,p_entity_type text,p_entity_id uuid,p_metadata jsonb default '{}'::jsonb) returns void language sql security definer set search_path=public as $$ insert into public.audit_logs(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),p_action,p_entity_type,p_entity_id,p_metadata) $$;
create function public.create_sale(p_customer_name text,p_sale_date date,p_notes text,p_paid_amount numeric,p_payment_method text,p_lines jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare v_sale uuid; v_line jsonb; v_product products%rowtype; v_total numeric:=0; v_has_service boolean:=false; v_qty numeric; begin if not public.is_admin() then raise exception 'forbidden'; end if; if jsonb_array_length(p_lines)=0 then raise exception 'sale requires lines'; end if; insert into sales(customer_name,sale_date,paid_amount,payment_method,notes,created_by) values(p_customer_name,p_sale_date,p_paid_amount,p_payment_method,p_notes,auth.uid()) returning id into v_sale; for v_line in select * from jsonb_array_elements(p_lines) loop select * into v_product from products where id=(v_line->>'product_id')::uuid and is_active for update; if not found or v_product.selling_price is null then raise exception 'item unavailable or unpriced'; end if; v_qty:=(v_line->>'quantity')::numeric; if v_qty<=0 then raise exception 'invalid quantity'; end if; if v_product.is_stock_tracked and v_product.stock_on_hand<v_qty then raise exception 'insufficient stock'; end if; if v_product.is_stock_tracked then update products set stock_on_hand=stock_on_hand-v_qty,updated_at=now() where id=v_product.id; insert into inventory_movements(product_id,quantity_delta,movement_type,reason,reference,recorded_by) values(v_product.id,-v_qty,'sale','Sale',v_sale::text,auth.uid()); else v_has_service:=true; end if; insert into sale_lines(sale_id,product_id,item_name_snapshot,unit_snapshot,quantity,unit_price) values(v_sale,v_product.id,v_product.name,v_product.unit,v_qty,v_product.selling_price); v_total:=v_total+(v_qty*v_product.selling_price); end loop; if p_paid_amount>v_total then raise exception 'payment exceeds total'; end if; update sales set total_amount=v_total,status=case when p_paid_amount=v_total then 'paid' else 'open' end,has_service_lines=v_has_service where id=v_sale; perform public.audit('sale.created','sale',v_sale,jsonb_build_object('total',v_total)); return v_sale; exception when others then raise; end $$;
create function public.create_payroll_record(p_employee_id uuid,p_period_start date,p_quantity numeric,p_notes text) returns uuid language plpgsql security definer set search_path=public as $$ declare e employees%rowtype; r uuid; a numeric; begin if not public.is_admin() then raise exception 'forbidden'; end if; select * into e from employees where id=p_employee_id and is_active for update; if not found then raise exception 'employee unavailable'; end if; if e.pay_type='monthly' then a:=e.rate; else a:=p_quantity*e.rate; end if; insert into payroll_records(employee_id,pay_type,period_start,quantity,rate_snapshot,amount,notes,created_by) values(e.id,e.pay_type,p_period_start,p_quantity,e.rate,a,p_notes,auth.uid()) returning id into r; perform public.audit('payroll.created','payroll',r); return r; end $$;
alter table public.company_settings enable row level security; alter table public.profiles enable row level security; alter table public.products enable row level security; alter table public.inventory_movements enable row level security; alter table public.sales enable row level security; alter table public.sale_lines enable row level security; alter table public.payments enable row level security; alter table public.employees enable row level security; alter table public.payroll_records enable row level security; alter table public.audit_logs enable row level security;
create policy profiles_self_or_super on public.profiles for select using(id=auth.uid() or public.is_super_admin()); create policy profiles_super_update on public.profiles for update using(public.is_super_admin()); create policy products_read on public.products for select using(auth.uid() is not null); create policy products_admin_write on public.products for all using(public.is_admin()) with check(public.is_admin()); create policy movement_read on public.inventory_movements for select using(public.is_admin()); create policy sales_admin on public.sales for select using(public.is_admin()); create policy sale_lines_admin on public.sale_lines for select using(public.is_admin()); create policy employees_admin on public.employees for all using(public.is_admin()) with check(public.is_admin()); create policy payroll_admin on public.payroll_records for all using(public.is_admin()) with check(public.is_admin()); create policy settings_read on public.company_settings for select using(auth.uid() is not null); create policy settings_super on public.company_settings for update using(public.is_super_admin()); create policy audit_super on public.audit_logs for select using(public.is_super_admin());
